CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 VARCHAR(10), c1 REAL UNIQUE, c2 BLOB, c3 INT UNIQUE, c4  DEFAULT 'd');
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 INTEGER, c1 TEXT COLLATE NOCASE, c2 VARCHAR(10), c3 NUMERIC, c4 TEXT COLLATE NOCASE);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4) VALUES(1, -1e308, 2.5, NULL, '0x1F');
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4) VALUES(970.7, -9223372036854775808, 'upsilon', '1e3', -608);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4) VALUES(' pad ', x'5f396e1a54', 'zeta', x'87e2dd63be', 'Lambda');
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4) VALUES(NULL, x'16', -2, -917, -479);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4) VALUES(-888.7, 'Ελλάδα', x'1f55d63b', 90, -4);
SELECT length('phi'), upper('phi'), lower('phi'), substr('phi', -3, 0), instr('phi', 'señor'), replace('phi', '', '_'), trim('phi'), ltrim('phi', 'ab'), hex('phi'), quote('phi'), unicode('phi'), 'phi' LIKE 'A%', 'phi' GLOB 'a*', char(67, 380), 'phi' || 'señor', 'phi' < 'señor', 'phi' = 'señor' COLLATE NOCASE;
SELECT length('tau'), upper('tau'), lower('tau'), substr('tau', 3, 3), instr('tau', 'eta'), replace('tau', 'e', 'XY'), trim('tau'), ltrim('tau', 'ab'), hex('tau'), quote('tau'), unicode('tau'), 'tau' LIKE 'A%', 'tau' GLOB 'a*', char(88, 696), 'tau' || 'eta', 'tau' < 'eta', 'tau' = 'eta' COLLATE NOCASE;
SELECT length('xi'), upper('xi'), lower('xi'), substr('xi', -2, 3), instr('xi', 'theta'), replace('xi', 'é', 'XY'), trim('xi'), ltrim('xi', 'ab'), hex('xi'), quote('xi'), unicode('xi'), 'xi' LIKE '%é%', 'xi' GLOB '*', char(77, 246), 'xi' || 'theta', 'xi' < 'theta', 'xi' = 'theta' COLLATE NOCASE;
SELECT length('sigma'), upper('sigma'), lower('sigma'), substr('sigma', -3, 0), instr('sigma', 'sigma'), replace('sigma', '', '_'), trim('sigma'), ltrim('sigma', 'ab'), hex('sigma'), quote('sigma'), unicode('sigma'), 'sigma' LIKE '%é%', 'sigma' GLOB 'a*', char(66, 426), 'sigma' || 'sigma', 'sigma' < 'sigma', 'sigma' = 'sigma' COLLATE NOCASE;
SELECT length(''), upper(''), lower(''), substr('', -3, 1), instr('', '1e3'), replace('', 'a', '_'), trim(''), ltrim('', 'ab'), hex(''), quote(''), unicode(''), '' LIKE 'A%', '' GLOB '*[a-m]*', char(73, 710), '' || '1e3', '' < '1e3', '' = '1e3' COLLATE NOCASE;
SELECT id, (SELECT count(*) FROM t1 WHERE t1.id <= t0.id) FROM t0 ORDER BY c4, id;
SELECT id FROM t0 WHERE id NOT IN (SELECT id FROM t1 WHERE iif(CAST(825 AS BLOB), 4 BETWEEN c0 AND c2, x'')) ORDER BY id;
SELECT id FROM t0 x WHERE NOT EXISTS (SELECT 1 FROM t1 y WHERE y.id = x.id + 3) ORDER BY id;
SELECT c3 FROM t0 EXCEPT SELECT c1 FROM t1 ORDER BY 1 LIMIT 29 OFFSET 3;
